Common_Movement_FaceOriginalDirection	face_down,end
scriptdefs
= Route111_WinstrateFamilysHouse_EventScript_Vicky
lock
faceplayer
setvar VAR_0x8008 LOCALID_WINSTRATE_HOUSE_VICKY
goto_if_set FLAG_TEMP_4 Route111_WinstrateFamilysHouse_EventScript_AlreadySpokenTo
msgbox	Es steht außer Frage, dass du stark bist.Aber würdest du gegen meinen Enkel kämpfen, würdest du am Ende vor Frust weinen.Er ist viel stärker als jeder TRAINER, den unsere Familie kennt.Er fordert inzwischen bestimmt schon den CHAMP der POKéMON-LIGA heraus.So wie ich meinen Enkel kenne, ist er vielleicht schon der CHAMP!
setflag FLAG_TEMP_4
goto Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
end
= Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
closemessage
applymovement VAR_0x8008 Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= Route111_WinstrateFamilysHouse_EventScript_AlreadySpokenTo
msgbox	Mein Enkel fordert inzwischen bestimmt schon den CHAMP der POKéMON-LIGA heraus.So wie ich ihn kenne, ist er vielleicht schon der CHAMP!
goto Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
end
= Route111_WinstrateFamilysHouse_EventScript_Victoria
lock
faceplayer
setvar VAR_0x8008 LOCALID_WINSTRATE_HOUSE_VICTORIA
goto_if_set FLAG_RECEIVED_MACHO_BRACE Route111_WinstrateFamilysHouse_EventScript_ReceivedMachoBrace
msgbox	Wir benutzen dieses MACHO-BAND, um unsere POKéMON im Training effektiver zu stärken.Da du uns alle hier besiegt hast, weiß ich nicht, ob du es brauchst, aber wir möchten dir gern unser MACHO-BAND schenken.
giveitem ITEM_MACHO_BRACE
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_RECEIVED_MACHO_BRACE
goto Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
end
= Route111_WinstrateFamilysHouse_EventScript_ReceivedMachoBrace
msgbox	Wenn es um POKéMON-Kämpfe geht, sind wir ziemlich leidenschaftlich.
goto Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
end
= Route111_WinstrateFamilysHouse_EventScript_Victor
lock
faceplayer
setvar VAR_0x8008 LOCALID_WINSTRATE_HOUSE_VICTOR
msgbox	Du bist der erste TRAINER, den ich so meisterhaft mit POKéMON kämpfen sehe.Aber ich muss dir sagen--mein Sohn ist stärker als du.Er hat sich sogar schon der POKéMON-LIGA gestellt, das kann ich dir sagen.
goto Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
end
= Route111_WinstrateFamilysHouse_EventScript_Vivi
lock
faceplayer
setvar VAR_0x8008 LOCALID_WINSTRATE_HOUSE_VIVI
msgbox	Mama ist stärker als Papa.Ich bin stärker als Mama.Und Oma ist stärker als ich!Aber mein großer Bruder ist noch stärker als Oma.
goto Route111_WinstrateFamilysHouse_EventScript_FaceOriginalDirection
end
